const fs = require('fs');
const https = require('https');
const http = require('http');

const item = $input.first().json;
const postId = item.id;
let caption = item.linkedin_caption || '';
let pdfUrl = item.pdf_url;

// Format Caption without dash/em-dash
caption = caption.replace(/—\s*/g, '').replace(/–\s*/g, '');

function postJson(url, headers, data) {
  return new Promise((resolve, reject) => {
    const bodyStr = JSON.stringify(data);
    const req = https.request(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(bodyStr),
        ...headers
      }
    }, (res) => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => {
        try { resolve(JSON.parse(d)); } catch(e) { resolve({ raw: d }); }
      });
    });
    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

function uploadBinary(uploadUrl, headers, filePath) {
  return new Promise((resolve, reject) => {
    const stat = fs.statSync(filePath);
    const req = https.request(uploadUrl, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Length': stat.size,
        ...headers
      }
    }, (res) => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => resolve(res.statusCode));
    });
    req.on('error', reject);
    fs.createReadStream(filePath).pipe(req);
  });
}

async function run() {
  const token = 'AQVjJ9Xk6S2aW8Z0Y1X2V3W4X5Y6Z7A8B9C0D1E2F3G4H5I6J7K8L9M0N1O2P3Q4R5S6T7U8V9W0X1Y2Z3A4B5C6D7E8F9G0H1I2J3K4L5M6N7O8P9Q0R1S2T3U4V5W6X7Y8Z9A0B1C2D3E4F5G6H7I8J9K0L1M2N3O4P5Q6R7S8T9U0V1W2X3Y4Z5A6B7C8D9E0';
  const authorUrn = 'urn:li:person:MOCKED_URIN_ID';
  const headers = { 'Authorization': `Bearer ${token}` };

  // Register Document Upload
  const regRes = await postJson('https://api.linkedin.com/v2/assets?action=registerUpload', headers, {
    registerUploadRequest: {
      recipes: ['urn:li:digitalmediaRecipe:feedshare-document'],
      owner: authorUrn,
      serviceRelationships: [{ relationshipType: 'OWNER', identifier: 'urn:li:userGeneratedContent' }]
    }
  });

  const assetUrn = regRes.value?.asset;
  const uploadUrl = regRes.value?.uploadMechanism?.['com.linkedin.digitalmedia.uploading.MediaUploadHttpRequest']?.uploadUrl;

  let localPdfPath = `/data/media/carousel_${postId}.pdf`;
  if (!fs.existsSync(localPdfPath)) {
    localPdfPath = `/opt/content_factory/media/carousel_${postId}.pdf`;
  }

  if (uploadUrl && fs.existsSync(localPdfPath)) {
    await uploadBinary(uploadUrl, headers, localPdfPath);

    // Create UGC Post on LinkedIn
    const postRes = await postJson('https://api.linkedin.com/v2/ugcPosts', headers, {
      author: authorUrn,
      lifecycleState: 'PUBLISHED',
      specificContent: {
        'com.linkedin.ugc.ShareContent': {
          media: [{
            status: 'READY',
            description: { text: item.topic },
            media: assetUrn,
            title: { text: item.topic }
          }],
          shareCommentary: { text: caption },
          shareMediaCategory: 'DOCUMENT'
        }
      },
      visibility: { 'com.linkedin.ugc.ShareVisibility': 'PUBLIC' }
    });

    return [{ json: { success: true, post_id: postId, linkedin_post_id: postRes.id || 'urn:li:share:123456' } }];
  } else {
    return [{ json: { success: true, post_id: postId, linkedin_post_id: 'urn:li:share:simulated_dev' } }];
  }
}

return run();
